const pounce = (dc) => act('Pounce', `If it moves at least 20 feet straight toward a creature and then hits it with a claw attack on the same turn, that target must succeed on a DC ${dc} Strength saving throw or be knocked prone. If the target is prone, it can make one bite attack against it as a bonus action.`);
const relentless = (n) => act('Relentless (Recharges after a Short or Long Rest)', `If it takes ${n} damage or less that would reduce it to 0 hit points, it is reduced to 1 hit point instead.`);
const tramplingCharge = (dc, what) => act('Trampling Charge', `If it moves at least 20 feet straight toward a creature and then hits it with a ${what} attack on the same turn, that target must succeed on a DC ${dc} Strength saving throw or be knocked prone. If the target is prone, it can make one stomp attack against it as a bonus action.`);
const webSense = act('Web Sense', 'While in contact with a web, knows the exact location of any other creature in contact with the same web.');
const webWalker = act('Web Walker', 'Ignores movement restrictions caused by webbing.');
const bloodFrenzy = act('Blood Frenzy', 'Has advantage on melee attack rolls against any creature that doesn\'t have all its hit points.');
const inkCloud = (r) => act('Ink Cloud (Recharges after a Short or Long Rest)', `A ${r}-foot-radius cloud of ink extends all around it if it is underwater. The area is heavily obscured for 1 minute, although a significant current can disperse the ink. After releasing the ink, it can use the Dash action as a bonus action.`);
const camo = act('Underwater Camouflage', 'Has advantage on Dexterity (Stealth) checks made while underwater.');
const illum = act('Illumination', 'Sheds bright light in a 10-foot radius and dim light for an additional 10 feet.');
const swarmImmune = { resist: ['bludgeoning', 'piercing', 'slashing'], conditionImmune: ['charmed', 'frightened', 'grappled', 'paralyzed', 'petrified', 'prone', 'restrained', 'stunned'] };
const swallow = (size, dmg) => act('Swallow', `Makes one bite attack against a ${size} or smaller target it is grappling. If the attack hits, the target is swallowed and the grapple ends. A swallowed target is blinded and restrained, has total cover, and takes ${dmg} acid damage at the start of each of the creature's turns. It can have only one target swallowed at a time. If the creature dies, the swallowed target can escape using 5 feet of movement, exiting prone.`);

